<?php
/** Read-only dashboard/day widget; no scheduler, no network, no database mutation. */
function wasteWidget(PDO $pdo,string $today):void {
 require_once __DIR__.'/operations.php';
 try{$version=opsReady($pdo)?',MAX(t.row_version) row_version':'';$q=$pdo->prepare("SELECT t.id,t.title,t.due_date,t.duration_minutes,t.done,p.name,p.address".$version.", GROUP_CONCAT(DISTINCT e.fraction ORDER BY e.fraction SEPARATOR ', ') fractions,GROUP_CONCAT(DISTINCT e.status SEPARATOR ', ') statuses,GROUP_CONCAT(DISTINCT s.name SEPARATOR ', ') sources,l.direction FROM waste_task_links l JOIN tasks t ON t.id=l.task_id JOIN waste_events e ON e.id=l.event_id JOIN properties p ON p.id=e.property_id JOIN waste_origins o ON o.event_id=e.id JOIN waste_sources s ON s.id=o.source_id WHERE (t.due_date BETWEEN ? AND ? OR (t.done=0 AND t.due_date<?)) GROUP BY t.id,t.title,t.due_date,t.duration_minutes,t.done,p.name,p.address,l.direction ORDER BY (t.due_date>=?) DESC,t.due_date,l.direction,p.name LIMIT 100");$q->execute([$today,planDate($today,1),$today,$today]);$rows=$q->fetchAll();
 echo '<section class="card"><h2>Müll: Heute raus / Heute rein / Morgen fällig</h2><a href="waste.php">Müllkalender und Quellenprüfung öffnen</a>';
 if(!$rows)echo '<p>Keine freigegebenen importierten Abfallaufgaben heute/morgen. Sonderregeln weiterhin in der Tagesplanung prüfen.</p>';
 foreach($rows as $r)echo '<p>'.e($r['due_date']<$today?'Überfällig '.$r['direction']:($r['due_date']===$today?'Heute '.$r['direction']:'Morgen '.$r['direction'])).': <a href="planner.php?date='.e($r['due_date']).'">'.e($r['name'].' · '.$r['address'].' · '.$r['fractions']).'</a> · '.(int)$r['duration_minutes'].' Min. · '.($r['done']?'Erledigt':'Offen').'</p><form method="post" action="planner.php?date='.e($r['due_date']).'"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="toggle"><input type="hidden" name="task_id" value="'.(int)$r['id'].'"><input type="hidden" name="done" value="'.($r['done']?'0':'1').'">'.(isset($r['row_version'])?'<input type="hidden" name="row_version" value="'.(int)$r['row_version'].'">':'').'<button>'.($r['done']?'Wieder öffnen':'Erledigt').'</button></form>';
 echo '</section>';
 }catch(PDOException $e){echo '<p><a href="waste.php">Müllkalender: Einrichtung/Quellen prüfen</a></p>';}
}
